import base64, hashlib, re

def sri(body: bytes) -> str:
    # 브라우저 SRI 와 같은 꼴: sha384-<base64>
    return "sha384-" + base64.b64encode(hashlib.sha384(body).digest()).decode()

# 승인 목록(6.4.3): 결제 페이지에 올라가도 되는 스크립트와 그 지문
approved = {
    "https://pay.example.tw/checkout.js": sri(b"function pay(){}"),
    "https://cdn.example.tw/analytics.js": sri(b"track('view')"),
}

def check(page_html, fetched):
    out = []
    for url in re.findall(r'<script[^>]+src="([^"]+)"', page_html):
        if url not in approved:
            out.append("승인 안 된 스크립트: " + url)
        elif sri(fetched[url]) != approved[url]:
            out.append("내용이 바뀜: " + url)
    return out or ["이상 없음"]

page = ('<script src="https://pay.example.tw/checkout.js"></script>'
        '<script src="https://cdn.example.tw/analytics.js"></script>')
ok = {"https://pay.example.tw/checkout.js": b"function pay(){}",
      "https://cdn.example.tw/analytics.js": b"track('view')"}
print(check(page, ok))

# 통계 스크립트에 카드 번호를 빼돌리는 줄이 끼고, 낯선 스크립트가 하나 붙었다
page2 = page + '<script src="https://evil.example/skim.js"></script>'
